<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {effects,type EffectId} from '../config/effects'
const props=defineProps<{effect:EffectId;text:string;senderLabel:string;previewOnly:boolean;sending:boolean;error:string}>()
const emit=defineEmits<{close:[];effect:[id:EffectId];text:[value:string];preview:[];send:[]}>()
const closeButton=ref<HTMLButtonElement>()
onMounted(()=>closeButton.value?.focus())
function keys(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();emit('close')}if(event.key==='Tab'){const nodes=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not([disabled]),textarea:not([disabled])')),first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
</script>
<template><div class="encouragement-backdrop" @click.self="emit('close')"><section class="encouragement-panel" role="dialog" aria-modal="true" aria-label="鼓励光效样板" @keydown="keys"><header><span>{{senderLabel}}</span><button ref="closeButton" aria-label="关闭鼓励浮层" @click="emit('close')">×</button></header><div class="effect-choices" role="group" aria-label="选择鼓励光效"><button v-for="item in effects" :key="item.id" :data-effect="item.id" :aria-pressed="effect===item.id" :disabled="sending" @click="emit('effect',item.id)"><span class="effect-thumbnail" :class="item.id" aria-hidden="true"><i v-for="index in 5" :key="index" :style="{'--i':index}"/></span><span>{{item.label}}</span></button></div><textarea :value="text" :disabled="sending" maxlength="200" rows="2" placeholder="留言（可选）" aria-label="鼓励留言，最多200字" @input="emit('text',($event.target as HTMLTextAreaElement).value)"/><p v-if="error" role="alert">{{error}}</p><footer><small>模拟流程 · 当前页面有效</small><div><button :disabled="sending" @click="emit('preview')">预览</button><button v-if="!previewOnly" class="send" :disabled="sending" @click="emit('send')">{{sending?'模拟发送中…':'模拟发送'}}</button></div></footer></section></div></template>
<style scoped>
.encouragement-backdrop{position:fixed;inset:0;z-index:12;background:#090f192b;display:flex;align-items:flex-end;justify-content:center;padding:24px 18px 60px;box-sizing:border-box}.encouragement-panel{width:min(510px,100%);padding:18px 22px 20px;box-sizing:border-box;background:#242c38f5;color:#e5e4df;border:1px solid #aeb9c32b;border-radius:20px;box-shadow:0 20px 80px #080d1955;font-size:12px;backdrop-filter:blur(10px)}header,footer{display:flex;justify-content:space-between;align-items:center}header span{letter-spacing:.08em;font-size:12px}button{font:inherit;color:inherit;cursor:pointer;background:transparent;border:0;min-width:44px;min-height:44px}header button{font-size:24px}.effect-choices{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:8px 0 18px}.effect-choices button{padding:8px 2px;border:1px solid transparent;border-radius:12px;font-size:11px;display:grid;justify-items:center;gap:7px}.effect-choices button[aria-pressed=true]{background:#c5aa7520;border-color:#d5ba7b60}.effect-thumbnail{position:relative;display:block;width:44px;height:44px}.effect-thumbnail i{position:absolute;left:calc(4px + var(--i)*6px);top:calc(6px + var(--i)*5px);width:3px;height:3px;border-radius:50%;background:#e9c68a;box-shadow:0 0 6px #edc78588;animation:glimmer 2.4s infinite;animation-delay:calc(var(--i)*-.2s)}.starlight i{width:1px;height:18px;border-radius:2px;background:linear-gradient(#e5f0ff,transparent);transform:rotate(38deg)}.resonance i{background:none;box-shadow:none;border:1px solid #bed0d9;width:calc(8px + var(--i)*5px);height:calc(5px + var(--i)*3px);left:50%;top:50%;transform:translate(-50%,-50%)}.bloom i{width:9px;height:20px;background:#d2ba8f44;border:1px solid #dbcaaf66;left:50%;top:48%;transform-origin:50% 100%;transform:translate(-50%,-100%) rotate(calc(var(--i)*72deg));box-shadow:none}.halo i{left:calc(19px + sin(var(--i)*60deg)*17px);top:calc(19px + cos(var(--i)*60deg)*12px);background:#dceafa}.effect-thumbnail{animation:float 3s infinite ease-in-out}.encouragement-panel textarea{box-sizing:border-box;width:100%;resize:none;font:inherit;color:inherit;background:#101a283d;border:1px solid #adbbc12b;border-radius:10px;padding:12px;line-height:1.7;outline:none}.encouragement-panel textarea::placeholder{color:#a0aab5}.encouragement-panel p{font-size:11px;color:#ebba97;line-height:1.6}footer{margin-top:12px;gap:10px}footer small{font-size:9px;color:#9ca8b3}footer>div{display:flex;gap:6px}.send{background:#b89c6866;border:1px solid #d9b97b66;border-radius:22px;padding:0 16px}button:disabled{opacity:.4;cursor:default}button:focus-visible,textarea:focus-visible{outline:2px solid #d2b783;outline-offset:3px}@keyframes glimmer{50%{opacity:.35}}@keyframes float{50%{transform:translateY(-2px)}}@media(prefers-reduced-motion:reduce){.effect-thumbnail,.effect-thumbnail i{animation:none}}@media(max-width:600px){.encouragement-backdrop{padding:12px 12px 48px}.encouragement-panel{padding:12px 14px 16px}.effect-choices{gap:2px}.effect-choices button{font-size:10px}footer{flex-wrap:wrap}}
</style>
